/**
 * @param {number[]} nums
 * @return {number[][]}
 */
var threeSum = function(nums) {
    nums.sort((a,b)=>a-b)
    let res=[]
    let set=new Set()
    for(let i=0;i<nums.length;i++){
        if(i>0 && nums[i]==nums[i-1]) continue
        let map=new Map()
        let temp=nums[i]
        for(let j=i+1;j<nums.length;j++){
            let diff=0-temp-nums[j]
            if( map.has(diff)){
                let k=map.get(diff)
                if (i !== j && i !== k && j !== k) {
                    let triplet=[temp,diff,nums[j]]
                    let key=triplet.sort((a,b)=>a-b).join(',')
                    if(!set.has(key)){
                        set.add(key)
                        res.push(triplet)
                    }
                }
            }
            map.set(nums[j],j)
        }
    }
    return res
};

