var minSubArrayLen = function(target, nums) {
    let left = 0;
    let right = 0;
    let sum = nums[left] 
    let minLength = Infinity;

    while (right < nums.length) {
        if (sum < target) {
            right++;
            if (right < nums.length) {
                sum += nums[right];
            }
        } else {
            minLength = Math.min(minLength, right - left + 1);
            sum -= nums[left];
            left++;
        }
    }
    if (minLength === Infinity) {
        return 0; 
    } else {
        return minLength; 
    }
};

