        if (odd.length > longest.length) {
            longest = odd;
        }

        if (even.length > longest.length) {
            longest = even;
        }
    }

    function expand(str, left, right) {
        while (
            left >= 0 &&
            right < str.length &&
            str[left] === str[right]
        ) {
            left--;
            right++;
        }

        return str.slice(left + 1, right);
    }

    return longest;
};

