/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var findPairs = function(nums, k) {
    let map = new Map()
    let count = 0

    if(k < 0) return 0

    for(let i = 0; i < nums.length; i++){
        if(!map.has(nums[i])) {
            map.set(nums[i], 1)
        }
        else {
            map.set(nums[i], map.get(nums[i]) + 1)
        }
    }

    for(let [key, value] of map.entries()){
        if(k === 0 && value > 1) {
            count++
        }
        else if(k > 0 && map.has(key + k)) {
            count++
        }
    }

    return count
};

