 * @param {string} t
 * @return {boolean}
 */
var backspaceCompare = function(s, t) {
    function compare(str){
        let hash=0
        let returnstr=''

        for(let i=str.length-1;i>=0;i--){
            if(str[i]=='#'){
                hash++
            }
            else {
                if(hash<=0){
                    returnstr+=str[i]
                }
                else if(hash>0){
                    hash--
                    continue
                }
            }
        }
        return returnstr
    }

    return compare(s)==compare(t)
};

