var mergeAlternately = function(word1, word2) {
    let range=word1.length>word2.length?word2.length:word1.length
    let i=0
    let merged=''
    while(i<range){
        merged+=word1[i]+word2[i]
        i++
    }
    if(i<word1.length){
        merged+=word1.slice(i,word1.length)
